/**
 * SLATE — the watchmakers and the jewelers, at catalog depth.
 *
 * Rolex, Patek Philippe, Audemars Piguet and Omega run reference numbers
 * rather than seasons: a Submariner is not one watch but a page of them, and
 * the reference is the product. Cartier, Tiffany, Bulgari and Van Cleef run
 * collections that go on for pages the same way. Thirteen Rolexes on a shelf
 * is a display case, not a maison.
 *
 * Public record: the maker, the collection, the reference and the metal.
 * SLATE's own arithmetic: every price and every quality figure. A steel
 * sports Rolex has a list price nobody can buy it at and a market price that
 * moves weekly; the number here is a calibration of what it costs to own
 * one, labeled as a calibration, and the waitlist tag says why the list
 * price is not the whole story.
 */

import { REFERENCE_VERSION } from './reference';
import { jewellerySlotFor } from './wardrobe';
import type { RealGood } from './goods';

const REAL = {
  source: 'calibrated_estimate', confidence: 'high', version: REFERENCE_VERSION,
  note: 'A real reference, named as public record. Price and quality are SLATE’s own calibration; a steel sports watch is worth what the market says that week.',
} as const;

const ALL_YEAR = ['Spring', 'Summer', 'Autumn', 'Winter'];

/** A watch. Depreciation goes negative on the references that appreciate. */
const wa = (
  id: string, name: string, brand: string, sub: string, price: number,
  quality: number, depreciation: number, tags: string[] = [],
): RealGood => ({
  id, name, type: 'product', category: 'watch', subcategory: sub, basePrice: price, brand,
  tags: ['watch', sub, ...tags], quality, depreciation, slot: 'watch', formality: 50,
  seasons: ALL_YEAR, ...REAL,
});

/** A piece of jewelry, hung on the peg it belongs to. */
const jw = (
  id: string, name: string, brand: string, sub: string, price: number,
  quality: number, depreciation: number, tags: string[] = [],
): RealGood => ({
  id, name, type: 'product', category: 'jewelry', subcategory: sub, basePrice: price, brand,
  tags: ['jewellery', sub, ...tags], quality, depreciation,
  slot: jewellerySlotFor(sub, name), formality: 60, seasons: ALL_YEAR, ...REAL,
});

/** Leather goods, eyewear and scent from a jeweler: an accessory, not a jewel. */
const ac = (
  id: string, name: string, brand: string, sub: string, price: number,
  slot: string | undefined, quality: number, depreciation: number,
): RealGood => ({
  id, name, type: 'product', category: 'accessory', subcategory: sub, basePrice: price, brand,
  tags: ['wear', sub], quality, depreciation, slot, formality: 40, seasons: ALL_YEAR,
  audience: 'unisex', ...REAL,
});

